package com.nigson.commerce.payment;

import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.order.OrderPolicy;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;

/** Refund value is reserved under the same order lock used by financial settlement. */
public final class JdbcPaymentRepository implements PaymentRepository {
 private final JdbcTemplate jdbc;private final Clock clock;private final OrderPolicy binding;
 public JdbcPaymentRepository(JdbcTemplate jdbc,Clock clock,OrderPolicy binding){this.jdbc=jdbc;this.clock=clock;this.binding=binding;}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private String money(Object value){return PaymentValues.money(((BigDecimal)value).stripTrailingZeros().toPlainString(),false);}
 private Map<String,Object> one(List<Map<String,Object>> rows){if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private Map<String,Object> lockOrder(UUID id){transaction();return one(jdbc.queryForList("SELECT * FROM commerce.sales_order WHERE id=? FOR UPDATE",id));}
 private void version(long actual,long expected){if(actual!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(actual==Long.MAX_VALUE)throw PaymentValues.rule();}
 public UUID order(UUID refund){return (UUID)one(jdbc.queryForList("SELECT order_id FROM commerce.refund WHERE id=?",refund)).get("order_id");}
 public PaymentValues.Payment payment(UUID order){var row=one(jdbc.queryForList("SELECT a.*,EXISTS(SELECT 1 FROM commerce.payment_transaction t JOIN commerce.sales_order o ON o.id=a.order_id WHERE t.attempt_id=a.id AND a.provider='PAYSTACK' AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND t.settled_amount=a.expected_amount AND a.expected_amount=o.grand_total AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND t.provider_mode=a.provider_mode AND a.provider_mode=CASE o.carrier_snapshot->>'mode' WHEN 'SANDBOX' THEN 'TEST' ELSE o.carrier_snapshot->>'mode' END AND t.provider_status='success') AS settled FROM commerce.payment_attempt a WHERE a.order_id=? ORDER BY a.created_at DESC,a.id DESC LIMIT 1",order));String url=(String)row.get("checkout_url");if(url!=null&&row.get("provider_mode").equals("MOCK")&&url.startsWith("http://"))url=null;return new PaymentValues.Payment(order,row.get("state").toString(),Boolean.TRUE.equals(row.get("settled")),row.get("reference").toString(),url);}
 public PaymentValues.Refund refund(UUID id,boolean lock){if(lock)transaction();var row=one(jdbc.queryForList("SELECT id,state,amount,currency_code,version FROM commerce.refund WHERE id=?"+(lock?" FOR UPDATE":""),id));return new PaymentValues.Refund(id,row.get("state").toString(),money(row.get("amount")),row.get("currency_code").toString(),((Number)row.get("version")).longValue());}
 public PaymentValues.RefundDetail detail(UUID id){var value=refund(id,false);String provider=jdbc.queryForObject("SELECT provider_refund_id FROM commerce.refund WHERE id=?",String.class,id);return new PaymentValues.RefundDetail(value.id(),value.state(),value.amount(),value.currency(),value.version(),provider);}
 private Map<String,Object> settlement(UUID order,Map<String,Object> owned){binding.require(EventCodec.JSON.readTree(owned.get("carrier_snapshot").toString()).path("mode").asString());var rows=jdbc.queryForList("SELECT a.id,a.provider_mode,a.merchant_account,a.expected_amount,t.settled_amount FROM commerce.payment_attempt a JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE a.order_id=? AND a.provider='PAYSTACK' AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.currency_code='NGN' AND t.currency_code=a.currency_code AND t.provider_mode=a.provider_mode AND t.provider_status='success' FOR UPDATE OF a",order);if(rows.size()!=1)throw PaymentValues.rule();var truth=rows.getFirst();if(!truth.get("provider_mode").equals(binding.mode())||!truth.get("merchant_account").equals(binding.merchantAccount())||!owned.get("currency_code").equals("NGN")||((BigDecimal)truth.get("expected_amount")).compareTo((BigDecimal)owned.get("grand_total"))!=0||((BigDecimal)truth.get("settled_amount")).compareTo((BigDecimal)truth.get("expected_amount"))!=0)throw PaymentValues.rule();return truth;}
 private BigDecimal reserved(UUID order){return jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state NOT IN ('FAILED','REJECTED')",BigDecimal.class,order);}
 private void history(UUID order,String before,String after,String reason,UUID actor){jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor.toString(),order,before,after,reason);}
 public PaymentValues.Refund request(UUID order,long expected,PaymentValues.RefundInput input,String businessKey,UUID actor){var owned=lockOrder(order);version(((Number)owned.get("version")).longValue(),expected);if(!Set.of("PAID","PARTIALLY_REFUNDED").contains(owned.get("payment_status"))||!Set.of("PAID","PROCESSING","SHIPPED","DELIVERED","PAYMENT_HOLD","REFUNDING").contains(owned.get("status")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(businessKey==null||!businessKey.matches("[a-f0-9]{64}"))throw ApiValues.invalid();var truth=settlement(order,owned);BigDecimal amount=new BigDecimal(input.amount()),settled=(BigDecimal)truth.get("settled_amount");if(reserved(order).add(amount).compareTo(settled)>0)throw PaymentValues.rule();BigDecimal succeeded=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state='SUCCEEDED'",BigDecimal.class,order);if(succeeded.compareTo((BigDecimal)owned.get("refunded_total"))!=0)throw PaymentValues.rule();
  BigDecimal lineSum=BigDecimal.ZERO;for(var line:input.lines()){var lines=jdbc.queryForList("SELECT l.quantity,l.line_total,s.quantity_scale FROM commerce.order_line l JOIN commerce.sku s ON s.id=l.sku_id WHERE l.id=? AND l.order_id=?",line.orderLineId(),order);if(lines.size()!=1)throw PaymentValues.rule();var saved=lines.getFirst();BigDecimal qty=new BigDecimal(line.quantity());if(qty.stripTrailingZeros().scale()>((Number)saved.get("quantity_scale")).intValue())throw PaymentValues.rule();var prior=one(jdbc.queryForList("SELECT coalesce(sum(l.quantity),0) AS quantity,coalesce(sum(l.amount),0) AS amount FROM commerce.refund_line l JOIN commerce.refund r ON r.id=l.refund_id WHERE l.order_line_id=? AND r.order_id=? AND r.state NOT IN ('FAILED','REJECTED')",line.orderLineId(),order));BigDecimal value=new BigDecimal(line.amount());if(((BigDecimal)prior.get("quantity")).add(qty).compareTo((BigDecimal)saved.get("quantity"))>0||((BigDecimal)prior.get("amount")).add(value).compareTo((BigDecimal)saved.get("line_total"))>0)throw PaymentValues.rule();lineSum=lineSum.add(value);}if(!input.lines().isEmpty()&&lineSum.compareTo(amount)!=0)throw PaymentValues.rule();
  UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.refund(id,created_by,updated_by,order_id,attempt_id,request_key,amount,currency_code,state,reason,requested_by,provider_reference) VALUES (?,?,?,?,?,?,?,'NGN','REQUESTED',?,?,?)",id,actor.toString(),actor.toString(),order,truth.get("id"),businessKey,amount,input.reason(),actor,"nigson-refund-"+id.toString().replace("-",""));for(var line:input.lines())jdbc.update("INSERT INTO commerce.refund_line(id,created_by,updated_by,refund_id,order_line_id,quantity,amount) VALUES (?,?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor.toString(),actor.toString(),id,line.orderLineId(),new BigDecimal(line.quantity()),new BigDecimal(line.amount()));jdbc.update("UPDATE commerce.sales_order SET version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),actor.toString(),order);history(order,owned.get("status").toString(),owned.get("status").toString(),input.reason(),actor);return refund(id,false);
 }
 public PaymentValues.Refund approve(UUID id,long expected,PaymentValues.Approval input,UUID actor,boolean twoPerson){UUID order=order(id);var owned=lockOrder(order);var before=refund(id,true);version(before.version(),expected);if(!before.state().equals("REQUESTED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);UUID requester=jdbc.queryForObject("SELECT requested_by FROM commerce.refund WHERE id=?",UUID.class,id);if(input.approve()&&twoPerson&&requester.equals(actor))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(((Number)owned.get("version")).longValue()==Long.MAX_VALUE)throw PaymentValues.rule();String after=owned.get("status").toString();if(input.approve()){var truth=settlement(order,owned);if(reserved(order).compareTo((BigDecimal)truth.get("settled_amount"))>0)throw PaymentValues.rule();if(new BigDecimal(before.amount()).add(jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state IN ('APPROVED','SUBMITTING','PENDING','UNKNOWN','SUCCEEDED')",BigDecimal.class,order)).compareTo((BigDecimal)truth.get("settled_amount"))==0&&!Set.of("SHIPPED","DELIVERED").contains(after))after="REFUNDING";}
  jdbc.update("UPDATE commerce.refund SET state=?,approved_by=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",input.approve()?"APPROVED":"REJECTED",actor,java.sql.Timestamp.from(clock.instant()),actor.toString(),id);jdbc.update("UPDATE commerce.sales_order SET status=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",after,java.sql.Timestamp.from(clock.instant()),actor.toString(),order);history(order,owned.get("status").toString(),after,input.reason(),actor);return refund(id,false);
 }
}
